package dev.hoi.client.screen.commander;

import dev.hoi.client.screen.dialog.DialogScreen;
import dev.hoi.protocol.dialog.*;
import net.fabricmc.fabric.api.client.gametest.v1.context.ClientGameTestContext;
import net.minecraft.client.gui.components.AbstractWidget;
import java.nio.file.*;
import java.util.*;

public final class CommanderAdvisorTest {
    private CommanderAdvisorTest() {}
    private static DialogView source(String directory,String name) throws java.io.IOException{return new DialogPayloads.Show(Files.readString(Path.of(directory,name+".json")),true).view().issued(UUID.randomUUID().toString(),3);}
    private static net.minecraft.client.input.MouseButtonEvent click(AbstractWidget button){return new net.minecraft.client.input.MouseButtonEvent(button.getX()+button.getWidth()/2,button.getY()+button.getHeight()/2,new net.minecraft.client.input.MouseButtonInfo(com.mojang.blaze3d.platform.InputConstants.MOUSE_BUTTON_LEFT,0));}
    private static boolean role(DialogView.Tile tile){return tile.traitNode()!=null&&tile.traitNode().kind().equals("advisor_role");}
    private static String action(DialogView view,boolean employed){return view.choices().stream().filter(c->c.id().endsWith(employed?"/dismiss":"/appoint")||c.label().equals(employed?"해임":"임명")&&view.tiles().stream().anyMatch(t->t.section().equals(c.id())&&role(t))).map(DialogView.Choice::id).findFirst().orElseThrow();}
    public static void run(ClientGameTestContext context,String directory) throws java.io.IOException {
        var tree=source(directory,"kor-advisor-role-tree");var sent=new ArrayList<DialogPayloads.Action>();context.setScreen(()->new CommanderTraits(tree,null,sent::add));context.waitTicks(3);context.takeScreenshot("hoi-commander-advisor-entry-gui2");
        context.runOnClient(client->{var screen=(CommanderTraits)client.gui.screen();var button=screen.choiceButton("advisor-roles");if(button==null||!button.active)throw new AssertionError("Static advisor role entry is clickable");screen.mouseClicked(click(button),false);screen.mouseClicked(click(button),true);if(!sent.equals(List.of(new DialogPayloads.Action(tree.token(),3,"advisor-roles"))))throw new AssertionError("Role entry sends one issued action");});
        var roles=source(directory,"kor-advisor-roles");sent.clear();context.setScreen(()->new CommanderTraits(roles,null,sent::add));context.waitTicks(3);context.takeScreenshot("hoi-commander-advisor-roles-gui2");
        String appointment=action(roles,false);
        context.runOnClient(client->{var screen=(CommanderTraits)client.gui.screen();var button=screen.choiceButton(appointment);if(button==null||!button.active)throw new AssertionError("Static role appointment is clickable");screen.mouseClicked(click(button),false);screen.mouseClicked(click(button),true);if(sent.size()!=1||!sent.getFirst().choice().equals(appointment))throw new AssertionError("Role selection sends its issued choice once");});
        var confirm=source(directory,"kor-advisor-confirm");var choices=new ArrayList<String>();context.setScreen(()->new DialogScreen(confirm){@Override protected void choose(String id){choices.add(id);}});context.waitTicks(3);context.takeScreenshot("hoi-commander-advisor-confirm-gui2");
        context.runOnClient(client->{var screen=(DialogScreen)client.gui.screen();String body=screen.bodyText().getString();if(!confirm.body().contains("£")||body.contains("£")||body.codePoints().filter(code->code>=0xe000&&code<=0xf8ff).count()<3)throw new AssertionError("Source advisor effect icons must render as keyword glyphs");var button=screen.children().stream().filter(c->c instanceof AbstractWidget).map(c->(AbstractWidget)c).filter(c->c.getMessage().getString().equals("취소")).findFirst().orElseThrow();screen.mouseClicked(click(button),false);if(!choices.equals(List.of("cancel")))throw new AssertionError("Confirmation cancellation sends cancel");});
        for(int[] size:List.of(new int[]{2560,1440},new int[]{1280,720}))for(String name:List.of("kor-advisor-roles","kor-advisor-selected","kor-admiral-roles","kor-advisor-admirals","kor-army-appointment-advisors","kor-jeon-advisor-roles")){
            var view=source(directory,name);boolean roleView=view.image().equals("commander/advisor-roles");var actions=new ArrayList<DialogPayloads.Action>();
            if(roleView&&view.tiles().stream().noneMatch(t->t.section().equals("leader")&&t.leader()!=null&&t.gauge()!=null))throw new AssertionError("Advisor roles must preserve the authoritative leader and experience gauge");
            context.getInput().resizeWindow(size[0],size[1]);context.runOnClient(client->client.options.guiScale().set(2));context.setScreen(()->roleView?new CommanderTraits(view,null,actions::add):new CommanderRoster(view,null,actions::add));context.getInput().setCursorPos(size[0]-5,80);context.waitTicks(3);context.takeScreenshot("hoi-commander-"+name+"-"+size[0]+"x"+size[1]+"-gui2");
            if(roleView){
                if(view.tiles().stream().filter(CommanderAdvisorTest::role).anyMatch(t->t.traitNode().available()))throw new AssertionError("Source role promotion must remain unavailable");
                long ownRoles=view.tiles().stream().filter(CommanderAdvisorTest::role).filter(t->t.traitNode().owned()).count();
                if(ownRoles!=(name.equals("kor-jeon-advisor-roles")?0:1))throw new AssertionError("Own role styling must be independent of employment");
                if(!view.choices().stream().filter(c->c.id().equals("traits")).findFirst().orElseThrow().label().equals("특성"))throw new AssertionError("Role return tab must retain the source label");
                var hero=view.tiles().stream().filter(t->t.leader()!=null).findFirst().orElseThrow();
                CommanderRosterTest.assertBoldHeaders(context,context.computeOnClient(client->client.gui.screen()),hero);
                if(name.equals("kor-advisor-roles")){
                    context.runOnClient(client->{var screen=(CommanderTraits)client.gui.screen();if(!screen.mouseScrolled(screen.x(70),screen.y(250),0,-100))throw new AssertionError("Owned trait pane must consume scrolling");});
                    context.waitTicks(2);context.takeScreenshot("hoi-commander-advisor-left-scrolled-"+size[0]+"x"+size[1]+"-gui2");
                    context.runOnClient(client->{var screen=(CommanderTraits)client.gui.screen();var seen=new boolean[]{false};var graphics=new net.minecraft.client.gui.GuiGraphicsExtractor(client,new net.minecraft.client.renderer.state.gui.GuiRenderState(),-1,-1){@Override public void text(net.minecraft.client.gui.Font font,net.minecraft.util.FormattedCharSequence line,int x,int y,int color,boolean shadow){var text=new StringBuilder();line.accept((index,style,code)->{text.appendCodePoint(code);return true;});if(text.toString().equals("특성 선택")){seen[0]=true;if(y+font.lineHeight>screen.y(331.5))throw new AssertionError("Owned trait footer must fit above the tactic box");}super.text(font,line,x,y,color,shadow);}};screen.extractRenderState(graphics,-1,-1,0);if(!seen[0])throw new AssertionError("Scrolling must reveal the full trait selection footer");screen.mouseScrolled(screen.x(70),screen.y(250),0,100);});
                    context.waitTicks(2);
                }
                if(view.tiles().stream().noneMatch(t->t.traitNode()!=null&&t.traitNode().owned()))throw new AssertionError("Reviewed advisor input must include owned trait nodes");
                context.runOnClient(client->{var screen=(CommanderTraits)client.gui.screen();for(var tile:view.tiles())if(tile.traitNode()!=null){if(!role(tile)&&screen.choiceButton(tile.section())!=null)throw new AssertionError("Owned advisor traits must remain informational");if(role(tile)){boolean offered=view.choices().stream().anyMatch(c->c.id().equals(tile.section()));if((screen.choiceButton(tile.section())!=null)!=offered)throw new AssertionError("Role controls must follow issued choices");if(!offered){screen.mouseClicked(new net.minecraft.client.input.MouseButtonEvent(screen.x(tile.traitNode().column()==1?475:152),screen.y(60+26*tile.traitNode().row()),new net.minecraft.client.input.MouseButtonInfo(com.mojang.blaze3d.platform.InputConstants.MOUSE_BUTTON_LEFT,0)),false);if(!actions.isEmpty())throw new AssertionError("Unavailable role must not submit");}}}});
                if(name.equals("kor-jeon-advisor-roles")){if(view.tiles().stream().filter(CommanderAdvisorTest::role).count()!=21||!actions.isEmpty())throw new AssertionError("Source-only roles must show all 21 disabled roles without issuing requests");continue;}
                String action=action(view,name.equals("kor-advisor-selected"));
                context.runOnClient(client->{var screen=(CommanderTraits)client.gui.screen();var button=screen.choiceButton(action);if(button==null||!button.active)throw new AssertionError("Available advisor role must be reachable");var point=click(button);screen.mouseClicked(new net.minecraft.client.input.MouseButtonEvent(point.x(),point.y(),new net.minecraft.client.input.MouseButtonInfo(com.mojang.blaze3d.platform.InputConstants.MOUSE_BUTTON_RIGHT,0)),false);if(!actions.isEmpty())throw new AssertionError("Right click must not appoint or dismiss an advisor");screen.mouseClicked(point,false);screen.mouseClicked(point,true);if(!actions.equals(List.of(new DialogPayloads.Action(view.token(),view.revision(),action))))throw new AssertionError("Advisor role must send one authenticated action");});
                actions.clear();context.setScreen(()->new CommanderTraits(view,null,actions::add));context.waitTicks(2);
                context.runOnClient(client->{var screen=(CommanderTraits)client.gui.screen();var button=screen.choiceButton("traits");if(button==null||!button.active)throw new AssertionError("Advisor roles must offer the issued traits return tab");screen.mouseClicked(click(button),false);screen.mouseClicked(click(button),true);if(!actions.equals(List.of(new DialogPayloads.Action(view.token(),view.revision(),"traits"))))throw new AssertionError("Traits return tab must retain server authority");});
                actions.clear();context.setScreen(()->new CommanderTraits(view,null,actions::add));context.waitTicks(2);
                context.runOnClient(client->{var screen=(CommanderTraits)client.gui.screen();var button=screen.choiceButton("preferred-tactic");boolean offered=view.choices().stream().anyMatch(c->c.id().equals("preferred-tactic"));if(button!=null){if(button.active!=offered)throw new AssertionError("Preferred tactic availability must match issued choices");screen.mouseClicked(click(button),false);screen.mouseClicked(click(button),true);}if(!actions.equals(offered?List.of(new DialogPayloads.Action(view.token(),view.revision(),"preferred-tactic")):List.of()))throw new AssertionError("Preferred tactic must only send an issued action once");});
                var withoutSheet=new DialogView(UUID.randomUUID().toString(),view.revision(),view.kind(),view.title(),view.subtitle(),view.body(),view.flag(),view.image(),view.sound(),view.tiles().stream().filter(t->role(t)||t.leader()==null&&t.traitNode()==null&&!t.section().equals("preferred-tactic-info")).toList(),view.choices().stream().filter(c->!Set.of("traits","preferred-tactic").contains(c.id())).toList());
                actions.clear();context.setScreen(()->new CommanderTraits(withoutSheet,null,actions::add));context.waitTicks(3);context.takeScreenshot("hoi-commander-advisor-no-source-sheet-synthetic-"+name+"-"+size[0]+"x"+size[1]+"-gui2");
                context.runOnClient(client->{var screen=(CommanderTraits)client.gui.screen();if(screen.choiceButton("traits")!=null||screen.choiceButton("preferred-tactic")!=null)throw new AssertionError("Missing source sheet must not invent detail or tactic controls");var button=screen.choiceButton(action);if(button==null||!button.active)throw new AssertionError("Advisor roles must remain usable without a source sheet");screen.mouseClicked(click(button),false);if(!actions.equals(List.of(new DialogPayloads.Action(withoutSheet.token(),withoutSheet.revision(),action))))throw new AssertionError("Source-less role view must retain its issued action");});
            }
        }
    }
}
